CREATE TABLE public.staff_permissions (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, capability text NOT NULL CHECK(capability IN ('support','billing','coaching','privacy','reports')), granted_by uuid, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,capability));
GRANT SELECT ON public.staff_permissions TO authenticated; GRANT ALL ON public.staff_permissions TO service_role;
ALTER TABLE public.staff_permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_own ON public.staff_permissions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.has_staff_permission(_user uuid,_capability text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user,'admin') OR EXISTS(SELECT 1 FROM public.staff_permissions WHERE user_id=_user AND capability=_capability) $$;
REVOKE ALL ON FUNCTION public.has_staff_permission(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_staff_permission(uuid,text) TO authenticated,service_role;
CREATE TABLE public.support_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, subject text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','resolved')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.support_tickets TO authenticated; GRANT ALL ON public.support_tickets TO service_role;
ALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_ticket ON public.support_tickets FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.support_replies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES public.support_tickets(id) ON DELETE CASCADE, author_id uuid, from_staff boolean NOT NULL DEFAULT false, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.support_replies TO authenticated; GRANT ALL ON public.support_replies TO service_role;
ALTER TABLE public.support_replies ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_reply ON public.support_replies FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.support_tickets WHERE id=ticket_id AND user_id=auth.uid()));
CREATE TABLE public.staff_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, author_id uuid, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.staff_notes TO service_role; ALTER TABLE public.staff_notes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.notification_preferences(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, announcements boolean NOT NULL DEFAULT true, expiry_reminders boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.notification_preferences TO authenticated; GRANT ALL ON public.notification_preferences TO service_role; ALTER TABLE public.notification_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_preferences ON public.notification_preferences FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.user_notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, body text NOT NULL, kind text NOT NULL CHECK(kind IN ('announcement','expiry')), dedupe_key text UNIQUE, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.user_notifications TO authenticated; GRANT ALL ON public.user_notifications TO service_role; ALTER TABLE public.user_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_notifications ON public.user_notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.privacy_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, kind text NOT NULL CHECK(kind IN ('export','delete')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','in_review','completed','declined')), reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.privacy_requests TO authenticated; GRANT ALL ON public.privacy_requests TO service_role; ALTER TABLE public.privacy_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_privacy ON public.privacy_requests FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE UNIQUE INDEX privacy_pending_unique ON public.privacy_requests(user_id,kind) WHERE status IN ('pending','in_review');
CREATE TABLE public.private_data_access(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, target_user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, resource text NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.private_data_access TO service_role; ALTER TABLE public.private_data_access ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.generation_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, operation text NOT NULL, status text NOT NULL CHECK(status IN ('success','failed','cancelled')), latency_ms integer NOT NULL, model text NOT NULL, input_tokens integer, output_tokens integer, cost_usd numeric, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.generation_events TO service_role; ALTER TABLE public.generation_events ENABLE ROW LEVEL SECURITY;
CREATE INDEX generation_events_date ON public.generation_events(created_at);
CREATE INDEX support_tickets_date ON public.support_tickets(created_at);